function showToast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4200);}
function setup(){
  $('game-grid').innerHTML=G.map((g,i)=>`<button class="game-tile" type="button" data-game="${esc(g.id)}" aria-label="${esc(g.title)}: jolastu"><span class="tile-image"><img loading="lazy" decoding="async" src="${esc(g.image.startsWith('data:')?g.image:(DEMO?'public/':'')+g.image)}" alt=""><span class="tile-number">${String(i+1).padStart(2,'0')}</span></span><span class="tile-body"><span class="tile-type">JOKOA · PDF ${g.page}. OR.</span><span class="tile-title">${esc(g.title)}</span><span class="tile-subtitle">${esc(g.subtitle)}</span><span class="tile-bottom"><span>JOLASTU</span><span>➜</span></span></span></button>`).join('');
  // The route map is navigable; every entry opens its real existing game.
  $('journey-list').innerHTML=G.map((g,i)=>`<li><button type="button" class="hb-route-game" data-route="${esc(g.id)}" aria-label="${i+1}. jokoa: ${esc(g.title)}"><span class="hb-route-number">${i+1}</span><span class="hb-route-icon">${esc(g.icon)}</span><span class="hb-route-text">${esc(g.title)}</span><span class="hb-route-status" aria-hidden="true">○</span></button></li>`).join('');
  $('journey-list').addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(!b)return;
    if(current?.gameId===b.dataset.route){$('journey-panel').classList.remove('open');return;}
    if(current&&!confirm('Uneko partida galduko duzu. Beste joko batera joan nahi duzu?'))return;
    $('journey-panel').classList.remove('open');$('mobile-journey-toggle').setAttribute('aria-expanded','false');openStart(b.dataset.route);
  });
  $('mobile-journey-toggle').addEventListener('click',()=>{const isOpen=$('journey-panel').classList.toggle('open');$('mobile-journey-toggle').setAttribute('aria-expanded',String(isOpen));});
  $('zoom-poster').addEventListener('click',()=>{if(!current)return;
    $('poster-zoom-image').src=imgSrc(current.question.image);
    $('poster-zoom-image').alt=`${current.question.page}. orrialdeko lamina historikoa`;
    $('zoom-page-label').textContent=`PDF ${current.question.page}. or.`;
    $('zoom-range').value=100;$('zoom-value').textContent='100 %';
    $('poster-zoom-image').style.width='100%';
    $('poster-dialog').showModal();
  });
  $('zoom-range').addEventListener('input',e=>{
    const v=Number(e.target.value);$('zoom-value').textContent=v+' %';
    $('poster-zoom-image').style.width=v+'%';
  });
  $('clear-answer').addEventListener('click',()=>{if(current&&!pending){if(current.question.type==='cityElectricGrid')egReset();else if(current.question.type==='workerMovementMatching')wmReset();else if(current.question.type==='workerChronology')chReset();else if(current.question.type==='cargoRoutes')cgResetSelection();else if(current.question.type==='beforeAfterEvidence')baReset();else if(current.question.type==='transportConsequencesBoard')coReset();else if(current.question.type==='industrializationEuropeMap')smReset();else if(current.question.type==='socialPyramidProfiles')spReset();else if(current.question.type==='urbanMigrationPress')upReset();else if(current.question.type==='enterprisePowerSimulation')epReset();else if(current.question.type==='factoryProductionSimulation')fpReset();else renderQuestion();}});
  $('hint-button').addEventListener('click',()=>{
    if(!current||pending)return;
    if(current.question.type==='cityElectricGrid'){egHint();return;}
     if(current.question.type==='workerMovementMatching'){wmHint();return;}
    if(current.question.type==='workerChronology'){chHint();return;}
    if(current.question.type==='cargoRoutes'){cgHint();return;}
    if(current.question.type==='beforeAfterEvidence'){baHint();return;}
    if(current.question.type==='transportConsequencesBoard'){coHint();return;}
    if(current.question.type==='industrializationEuropeMap'){smHint();return;}
    if(current.question.type==='socialPyramidProfiles'){spHint();return;}
    if(current.question.type==='urbanMigrationPress'){upHint();return;}
    if(current.question.type==='enterprisePowerSimulation'){epHint();return;}
    if(current.question.type==='factoryProductionSimulation'){fpHint();return;}
    if(current.question.hint){showToast('💡 PISTA · '+current.question.hint);return;}
    const hints={spot:'Bilatu laborantzak lau zatitan txandakatzen dituen laukitxoa.',choice:'Begiratu PDFko mapari edo irudi nagusiari.',year:'Erreparatu garaien hasiera eta amaiera datei.',match:'Erreparatu kontzeptu bakoitzaren definizioari.',sort:'Banandu nekazaritzako hobekuntzak eta kapitalaren erabilera.',verdict:'Irakurri baieztapen bakoitza eta konparatu iturriarekin.',order:'Bilatu zerk gertatu behar duen lehenik.',cloze:'Irakurri esaldi osoa, hutsuneak betetzen hasi aurretik.'};
    showToast('💡 PISTA · '+hints[current.question.type]);
  });
  $('next-answer').addEventListener('click',()=>{if(!pending||!current)return;
    if(pending.finished)showResult(pending);
    else{current.question=pending.question;current.points=pending.points;current.step=pending.step;renderQuestion();}
  });
  $('game-grid').addEventListener('click',e=>{const b=e.target.closest('[data-game]');if(b)openStart(b.dataset.game);});
  $('rank-select').innerHTML=G.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('');
  $('rank-select').addEventListener('change',e=>{rankGame=e.target.value;refreshRanking();});
  $('refresh-ranking').addEventListener('click',()=>refreshRanking());
  $('player-form').addEventListener('submit',beginGame);
  $('start-dialog').addEventListener('close',()=>{startGameCandidate=null;});
  document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
  $('back-home').addEventListener('click',()=>{if(!current||confirm('Partida utzi nahi duzu? Uneko aurrerapena galduko da.'))home();});
  $('end-early').addEventListener('click',()=>{if(current && confirm('Partida amaitu nahi duzu? Uneko puntuak gordeko dira.'))endEarly();});
  $('submit-answer').addEventListener('click',submitAnswer);
  wmBind();
  egBind();
  cgBindClicks();
  coBindClicks();
  fpBind();
  epBind();smBind();spBind();upBind();
  $('play-again').addEventListener('click',()=>{$('result-dialog').close();openStart(pickedGame);});
  $('result-home').addEventListener('click',()=>{$('result-dialog').close();home();});
  $('top-home').addEventListener('click',e=>{if(current){e.preventDefault();if(confirm('Partida utzi nahi duzu? Uneko aurrerapena galduko da.'))home();}});
  if(DEMO){$('pin-fields').classList.add('hidden');$('pin').required=false;markConnection('local');}
  else checkConnection();
  refreshRanking();
  // No unnecessary leaderboard repaints while the user is not viewing it.
  // While ranking is visible, its 12-second refresh behavior stays unchanged.
  setInterval(()=>{if(!document.hidden&&!$('sailkapena').hidden)refreshRanking(true);},12000);
}
function markConnection(mode){
  const c=$('connection');
  c.classList.remove('connected','offline');
  if(mode==='online'){c.classList.add('connected');c.innerHTML='<span class="signal-dot"></span> ONLINE · PARTEKATUA';}
  else if(mode==='local'){c.innerHTML='<span class="signal-dot"></span> PROBA LOKALA';c.classList.add('offline');}
  else{c.innerHTML='<span class="signal-dot"></span> KONEXIORIK EZ';c.classList.add('offline');}
  const tag=$('rank-live');
  if(mode!=='online')tag.textContent=mode==='local'?'PROBA LOKALA':'EZ DAGO KONEXIORIK';
  else tag.innerHTML='<span class="signal-dot"></span> ZUZENEAN';
}
async function checkConnection(){
  try{const r=await fetch('api/health',{cache:'no-store'});if(!r.ok)throw Error('No');serverOK=true;markConnection('online');}
  catch{serverOK=false;markConnection('offline');}
}
async function api(path,payload){
  const res=await fetch('api/'+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),cache:'no-store'});
  const data=await res.json().catch(()=>({error:'Ezin izan da erantzuna irakurri.'}));
  if(!res.ok)throw Error(data.error||'Sareko errorea.');
  return data;
}
async function refreshRanking(silent=false){
  if(rankingBusy)return;rankingBusy=true;
  try{
    const target=rankGame;
    let rows=[];
    if(window.HB_CLOUD?.joined){rows=await window.HB_CLOUD.leaderboard(target);}else if(DEMO){const store=safeGet('industria-demo-rankings',{});rows=Object.values(store[target]||{}).sort((a,b)=>b.score-a.score||a.elapsedMs-b.elapsedMs).slice(0,10);}
    else{const r=await fetch('api/leaderboard?game='+encodeURIComponent(target),{cache:'no-store'});if(!r.ok)throw Error('Rank');const d=await r.json();rows=d.entries||[];}
    if(target!==rankGame)return;
    $('ranking-rows').innerHTML=rows.length?rows.map((r,i)=>`<div class="rank-row"><span class="rank-medal">${['🥇','🥈','🥉'][i]||String(i+1)+'.'}</span><div class="rank-person">${esc(r.name)}<small>${Math.round((r.elapsedMs||0)/1000)} s</small></div><span class="rank-score">${Number(r.score).toLocaleString('eu-ES')} pt</span></div>`).join(''):'<div class="rank-empty">Oraindik ez dago errekorrik.<br><strong>Izan zaitez lehena!</strong></div>';
  }catch{if(!silent)$('ranking-rows').innerHTML='<div class="rank-empty">Sailkapena ezin da kargatu. Egiaztatu konexioa.</div>';}
  finally{rankingBusy=false;}
}
function openStart(id){
  if(!game(id))return;
  startGameCandidate=id;
  const g=game(id);
  $('start-title').textContent='Ongi etorri HistoriaBizira!';
  $('start-description').textContent=g.title+'. '+(window.HB_CLOUD?.joined?g.subtitle:DEMO?'Tokiko aurrebista: ez da PINik egiaztatzen eta emaitzak arakatzaile honetan bakarrik gordetzen dira.':g.subtitle);
  $('start-error').textContent='';
  $('nickname').value=window.HB_CLOUD?.joined?window.HB_CLOUD.session.nickname:safeGet('industria-nickname','');
  $('nickname').readOnly=!!window.HB_CLOUD?.joined;
  $('pin').value='';
  v61StartDetails(id);
  $('start-dialog').showModal();
  setTimeout(()=>$('nickname').focus(),50);
}
async function beginGame(e){
  e.preventDefault();if(submitting)return;
  const startingGame=startGameCandidate||pickedGame;
  const nick=$('nickname').value.trim().normalize('NFC');
  const pin=$('pin').value.trim();
  if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(nick)){$('start-error').textContent='Sartu 2–18 karaktereko goitizen bat.';return;}
  if(window.HB_CLOUD?.configured&&!window.HB_CLOUD?.joined){window.HB_CLOUD.change();return;}
  if(window.HB_CLOUD?.joined&&nick!==window.HB_CLOUD.session.nickname){$('start-error').textContent='Erabili ikasgelako goitizen bera: '+window.HB_CLOUD.session.nickname;return;}
  if(!DEMO&&!/^\d{6,10}$/.test(pin)){$('start-error').textContent='PINak 6–10 zenbaki behar ditu.';return;}
  const b=$('start-submit');submitting=true;b.disabled=true;b.textContent='KARGATZEN…';$('start-error').textContent='';
  try{
    const data=DEMO?demoStart(startingGame,nick):await api('start',{gameId:startingGame,nickname:nick,pin});
    egCleanup();wmCleanup();chCleanup();hbtrCleanup();v10Cleanup();fpCleanup();
    safeSet('industria-nickname',nick);
    v61Abandoned();
    pickedGame=startingGame;v61Select(startingGame);startGameCandidate=null;
    current={...data,gameId:startingGame,localStart:Date.now(),expired:false};
    v61Started();
    window.HB_CLOUD?.started(startingGame);
    $('start-dialog').close();
    $('home-screen').classList.add('hidden');$('play-screen').classList.remove('hidden');
    document.body.classList.remove('v6-cover','v6-menu','v6-catalog');
    document.body.classList.add('hb-playing');document.body.classList.toggle('hb-sectors-playing',pickedGame==='sektoreak');document.body.classList.toggle('hb-transport-playing',pickedGame==='garraioa'||pickedGame==='bigarrena'||pickedGame==='hedapena');document.body.classList.toggle('hb-origin-playing',pickedGame==='hasiera'||pickedGame==='industria_denbora_v1');document.body.classList.toggle('hb-timeline-playing',pickedGame==='industria_denbora_v1');$('header-play-progress').classList.remove('hidden');
    $('play-title').textContent=game(pickedGame).title;
    $('play-subtitle').textContent=pickedGame==='hasiera'?'6 erronka · 5 jarduera-mota · Jatorrizko PDFaren arabera':pickedGame==='industria_denbora_v1'?'Bi Industria Iraultzak · 6 ikerketa · PDFaren iturriak':game(pickedGame).subtitle;
    refreshJourney();
    $('play-section').textContent=`${G.findIndex(g=>g.id===pickedGame)+1}. JOLASA`;
    $('play-kind').textContent=window.HB_CLOUD?.joined?'IKASGELA · ONLINE':DEMO?'PROBA LOKALA':'ONLINE PARTIDA';
    pending=null;renderQuestion();updateStats();
    clearInterval(clock);clock=setInterval(tick,250);
    window.scrollTo(0,0);
  }catch(err){$('start-error').textContent=err.message||'Ezin da partida hasi. Konexioa egiaztatu.';}
  finally{submitting=false;b.disabled=false;b.innerHTML='▶ &nbsp; PARTIDA HASI';}
}
function demoStart(id,nick){
  const bank=window.INDUSTRIA_DEMO_BANK[id];
  const sequence=(id==='bigarrena'||id==='hedapena'||id==='gizartea'||id==='denbora'||id==='mugimendua')?bank.map((_,i)=>i):(id==='hasiera'||id==='industria_denbora_v1'||id==='sektoreak'||id==='garraioa')?bank.map((_,i)=>i):arrShuffle(bank.map((_,i)=>i));
  const state={nickname:nick,sequence,index:0,points:0,gameId:id};
  window._demoState=state;
  return {sessionId:'demo',sessionToken:'demo',gameId:id,nickname:nick,startedAt:Date.now(),
    timeLimitSeconds:(id==='sektoreak'||id==='garraioa'||id==='bigarrena'||id==='hedapena'||id==='gizartea'||id==='denbora'||id==='mugimendua'||id==='azkena')?900:(id==='hasiera'||id==='industria_denbora_v1')?720:240,step:1,total:bank.length,points:0,question:demoView(bank[sequence[0]])};
}
function demoView(q){
  const base={type:q.type,prompt:q.prompt,page:q.page,image:`assets/slides/p${String(q.page).padStart(2,'0')}.webp`,title:q.title,instruction:q.instruction,hint:q.hint,sourcePages:q.sourcePages,figure:q.figure,visuals:q.visuals};
  if(q.type==='industrializationEuropeMap')return {...base};
  if(q.type==='socialPyramidProfiles')return {...base};
  if(q.type==='cityElectricGrid')return {...base};
  if(q.type==='workerMovementMatching')return {...base};
  if(q.type==='workerChronology')return {...base};
  if(q.type==='urbanMigrationPress')return {...base};
  if(q.type==='factoryProductionSimulation')return {...base};
  if(q.type==='enterprisePowerSimulation')return {...base};
  if(q.type==='cargoRoutes')return {...base};
  if(q.type==='beforeAfterEvidence')return {...base,statements:baCore.STATEMENTS.map(({id,title,short,icon,pages,era})=>({id,title,short,icon,pages,era}))};
  if(q.type==='transportConsequencesBoard')return {...base};
  if(q.type==='inventorDesk')return {...base,facts:q.facts.map(({id,label,shortLabel})=>({id,label,shortLabel})),clues:q.clues.map(c=>({...c})),yearTokens:[...q.yearTokens]};
  if(q.type==='steamship')return {...base,innovations:q.innovations.map(c=>({...c}))};
  if(q.type==='railbuild')return {...base};
  if(q.type==='sectorboard')return {...base,slots:q.slots,fixed:q.fixed,cards:arrShuffle(q.cards.map(c=>({id:c.id,text:c.text,art:c.art}))),extraRelations:(q.extraRelations||[]).map(r=>({id:r.id,prompt:r.prompt,options:arrShuffle(r.options)}))};
  if(q.type==='sectorfix')return {...base,cases:q.cases.map(c=>({id:c.id,wrong:c.wrong,options:arrShuffle(c.options)}))};
  if(q.type==='factorysim')return {...base,scene:q.scene,scenarios:q.scenarios.map(s=>({id:s.id,kicker:s.kicker,title:s.title,lead:s.lead,question:s.question,scene:s.scene,sceneAlt:s.sceneAlt,impact:s.impact,options:arrShuffle(s.options)})),conclusion:{...q.conclusion,options:arrShuffle(q.conclusion.options)}};
  if(q.type==='timeline')return {...base,mode:q.mode,slots:q.slots,cards:arrShuffle(q.cards),initial:q.initial||{}};
  if(q.type==='choice')return {...base,options:arrShuffle(q.options)};
  if(q.type==='order')return {...base,items:arrShuffle(q.items)};
  if(q.type==='match')return {...base,left:arrShuffle(q.pairs.map(x=>x.left)),right:arrShuffle(q.pairs.map(x=>x.right))};
  if(q.type==='spot')return {...base,hotspots:q.hotspots.map(h=>({id:h.id,x:h.x,y:h.y}))};
  if(q.type==='spotmap')return {...base,labels:arrShuffle(q.labels),hotspots:q.hotspots.map(h=>({id:h.id,x:h.x,y:h.y}))};
  if(q.type==='sort')return {...base,bins:q.bins,cards:arrShuffle(q.cards.map(x=>({id:x.id,text:x.text})))};
  if(q.type==='verdict')return {...base,statements:arrShuffle(q.statements.map(x=>({id:x.id,text:x.text})))};
  if(q.type==='year')return {...base,min:q.min,max:q.max};
  if(q.type==='cloze')return {...base,parts:q.parts,blanks:q.blanks.map(b=>({id:b.id})),bank:arrShuffle(q.bank)};
}
function demoMark(q,a){
  if(q.type==='cityElectricGrid'){const r=egCore.evaluate(a);return {points:r.points,expected:r.expected};}
  if(q.type==='workerMovementMatching'){const r=wmCore.evaluate(a);return {points:r.points,expected:r.expected};}
  if(q.type==='workerChronology'){const r=chCore.evaluate(a);return {points:r.points,expected:r.expected};}
  if(q.type==='socialPyramidProfiles'){const mark=spCore.evaluate(a);return {points:mark.points,expected:spCore.solution()};}
  if(q.type==='urbanMigrationPress'){const mark=upCore.evaluate(a);return {points:mark.points,expected:mark.expected};}
  if(q.type==='industrializationEuropeMap'){const mark=smCore.evaluate(a);return {points:mark.points,expected:Object.fromEntries(smCore.TERRITORIES.map(t=>[t.label,smCore.GROUPS.find(g=>g.id===t.group).label]))};}
  if(q.type==='enterprisePowerSimulation'){const mark=epCore.evaluate(a);return {points:mark.points,expected:{'Akzioak':'A 4 · B 3 · C 2 · D 3','Inbertsioak':'M2 + L2 (12 unitate)','Enpresa-sarea':'Sei lotura nagusiak, PDF 22','Aztertu eta erabaki':'Bazkideak, kapitalaren partaidetzak, makinak eta langileak, inbertsioak eta merkatuak'}};}
  if(q.type==='factoryProductionSimulation'){const mark=fpCore.evaluate(a);return {points:mark.points,expected:{'Taylorismoa':'Denborak neurtzea, espezializazioa, lanaren araberako soldata','Kateko lana':'Piezak → Muntaketa → Kalitatea → Biltegia','Serieko ekoizpena':'Produktu berdin ugari, prezioak jaitsi','A kasua':'Taylorismoa eta kateko lana','B kasua':'Serieko ekoizpena','C kasua':'Hiru sistemak batera','Emaitzak':'55 s-ko muntaketa-fasea, lanaren antolaketa eta produktu berdin ugari'}};}
  if(q.type==='cargoRoutes')return cgCore.evaluate(a);
  if(q.type==='beforeAfterEvidence'){const mark=baCore.evaluated(a);return {points:mark.points,expected:Object.fromEntries(baCore.STATEMENTS.map(x=>[x.title,x.supported?'PDFan oinarrituta':'Ez dago PDFan bermatuta']))};}
  if(q.type==='transportConsequencesBoard'){const mark=coCore.evaluate(a);return {points:mark.points,expected:coCore.expected()};}
  if(q.type==='inventorDesk'){const mark=dkCore.evaluate(a);return {points:mark.points,expected:Object.fromEntries(q.facts.map(f=>[f.label,f.correctYear]))};}
  if(q.type==='steamship'){const mark=ssCore.evaluate(a);return {points:mark.points,expected:'Lurrun-makina erabiltzea nabigazioan · erregaia, galdara, 3/4 joko-indar eta palanka.'};}
  if(q.type==='railbuild'){const result=rbCore.validate(a);return {points:result.valid?100:0,expected:result.valid?'Bikain! Trenbidea osatu duzu!':result.errors.join(' · ') };}
  if(q.type==='sectorboard'){
    const placed=q.cards.filter(c=>a?.placements?.[c.id]===c.slot).length;
    const rels=(q.extraRelations||[]).filter(r=>a?.relations?.[r.id]===r.answer).length;
    const max=q.cards.length+(q.extraRelations||[]).length;
    return {points:Math.round(100*(placed+rels)/max),expected:{...Object.fromEntries(q.cards.map(c=>[c.text,q.slots.find(s=>s.id===c.slot)?.label+' · '+sectorSectorName[c.slot[0]==='e'?'textile':'steel']])),...Object.fromEntries((q.extraRelations||[]).map(r=>[r.prompt,r.answer]))}};
  }
  if(q.type==='sectorfix'){
    const correct=q.cases.filter(c=>a?.[c.id]===c.answer).length;
    return {points:Math.round(100*correct/q.cases.length),expected:Object.fromEntries(q.cases.map(c=>[c.wrong,c.answer]))};
  }
  if(q.type==='factorysim'){
    const expected={};
    let correct=0,total=q.scenarios.length+1;
    for(const s of q.scenarios){
      expected[s.title]=s.answer;
      if(a?.problems?.[s.id]===s.answer)correct++;
    }
    expected[q.conclusion.title]=q.conclusion.answer;
    if(a?.conclusion===q.conclusion.answer)correct++;
    return {points:Math.round(100*correct/total),expected};
  }
  if(q.type==='timeline'){const ids=Object.keys(q.answer),correct=ids.filter(id=>a?.[id]===q.answer[id]).length;return {points:Math.round(100*correct/ids.length),expected:Object.fromEntries(ids.map(id=>[q.cards.find(c=>c.id===id)?.label||id,q.slots.find(s=>s.id===q.answer[id])?.label||q.answer[id]]))};}
  if(q.type==='choice')return {points:a===q.answer?100:0,expected:q.answer};
  if(q.type==='spot')return {points:a===q.answer?100:0,expected:q.hotspots.find(h=>h.id===q.answer)?.label};
  if(q.type==='spotmap'){const n=Object.keys(q.answer).filter(k=>a?.[k]===q.answer[k]).length;return {points:Math.round(100*n/Object.keys(q.answer).length),expected:q.answer};}
  if(q.type==='year'){
    const d=Number.isInteger(a)?Math.abs(a-q.year):Infinity;
    return {points:d===0?100:d===1?75:d<=3?35:0,expected:String(q.year)};
  }
  if(q.type==='order'){
    const ids=q.items.map(x=>x.id),n=Array.isArray(a)?a.filter((x,i)=>x===ids[i]).length:0;
    return {points:Math.round(100*n/ids.length),expected:q.items.map(x=>x.label)};
  }
  if(q.type==='match'){
    const expected=Object.fromEntries(q.pairs.map(x=>[x.left,x.right]));
    const n=Object.keys(expected).filter(k=>a?.[k]===expected[k]).length;
    return {points:Math.round(100*n/Object.keys(expected).length),expected};
  }
  if(q.type==='sort'){
    const expected=Object.fromEntries(q.cards.map(c=>[c.text,q.bins.find(b=>b.id===c.bin)?.label]));
    const n=q.cards.filter(c=>a?.[c.id]===c.bin).length;
    return {points:Math.round(100*n/q.cards.length),expected};
  }
  if(q.type==='verdict'){
    const expected=Object.fromEntries(q.statements.map(x=>[x.text,x.truth?'EGIA':'GEZURRA']));
    const n=q.statements.filter(x=>a?.[x.id]===x.truth).length;
    return {points:Math.round(100*n/q.statements.length),expected};
  }
  if(q.type==='cloze'){
    const expected=Object.fromEntries(q.blanks.map((b,i)=>[`${i+1}. hutsunea`,b.answer]));
    const n=q.blanks.filter(b=>a?.[b.id]===b.answer).length;
    return {points:Math.round(100*n/q.blanks.length),expected};
  }
}
function demoFinish(){
  const s=window._demoState;
  const limitMs=roundTime()*1000;
  const elapsedMs=Math.min(limitMs,Date.now()-current.localStart);
  const basePoints=(s.gameId==='bigarrena'||s.gameId==='gizartea')?s.points*3:(s.gameId==='denbora'||s.gameId==='mugimendua'||s.gameId==='azkena')?s.points*6:s.gameId==='hedapena'?smCore.evaluate(smCore.serialize(smState||{})).basePoints:s.points;
  const score=Math.min(800,basePoints+Math.round(200*(basePoints/600)*(1-elapsedMs/limitMs)));
  const all=safeGet('industria-demo-rankings',{});
  if(s.gameId==='sektoreak'&&!all._hb10SectScoresSeparated){
    if(all.sektoreak)all.sektoreak_v9_archive=all.sektoreak;
    all.sektoreak={};all._hb10SectScoresSeparated=true;
  }
  if(s.gameId==='hedapena'&&!all._hb13HedapenaOneMap){if(all.hedapena)all.hedapena_6_errokak_archive=all.hedapena;all.hedapena={};all._hb13HedapenaOneMap=true;}
   if(s.gameId==='bigarrena'&&!all._hb11BigarrenaTwoChallenges){
    if(all.bigarrena)all.bigarrena_6_errokak_archive=all.bigarrena;
    all.bigarrena={};all._hb11BigarrenaTwoChallenges=true;
  }
  if(s.gameId==='gizartea'&&!all._hb21GizarteaTwoChallenges){if(all.gizartea)all.gizartea_6_errokak_archive=all.gizartea;all.gizartea={};all._hb21GizarteaTwoChallenges=true;}
  if(s.gameId==='denbora'&&!all._hb23DenboraOneChallenge){if(all.denbora)all.denbora_6_errokak_archive=all.denbora;all.denbora={};all._hb23DenboraOneChallenge=true;}
  if(s.gameId==='mugimendua'&&!all._hb24MugimenduaOneChallenge){if(all.mugimendua)all.mugimendua_6_errokak_archive=all.mugimendua;all.mugimendua={};all._hb24MugimenduaOneChallenge=true;}
  if(s.gameId==='azkena'&&!all._hb33ElectricOneChallenge){if(all.azkena)all.azkena_six_challenges_archive=all.azkena;all.azkena={};all._hb33ElectricOneChallenge=true;}
  all[s.gameId]??={};const key=s.nickname.toLocaleLowerCase('eu');
  const old=all[s.gameId][key];
  if(!old||score>old.score||(score===old.score&&elapsedMs<old.elapsedMs))all[s.gameId][key]={name:s.nickname,score,elapsedMs};
  safeSet('industria-demo-rankings',all);
  return {finished:true,points:s.points,score,elapsedSeconds:Math.round(elapsedMs/1000),step:s.index,total:window.INDUSTRIA_DEMO_BANK[s.gameId].length};
}
function demoAnswer(a){
  const s=window._demoState,bank=window.INDUSTRIA_DEMO_BANK[s.gameId];
  if(s.index>=bank.length)return demoFinish();
  const q=bank[s.sequence[s.index]],mark=demoMark(q,a);
  s.points+=mark.points;s.index++;
  const feedback={roundPoints:mark.points,explanation:q.note,expected:mark.expected};
  if(s.index===bank.length)return {...demoFinish(),feedback};
  return {finished:false,points:s.points,step:s.index+1,total:bank.length,feedback,question:demoView(bank[s.sequence[s.index]])};
}
function refreshJourney(){
  const completed=v61Completed();
  const completedCount=G.filter(g=>completed[g.id]===true).length;
  $('journey-progress-count').textContent=completedCount+' / '+G.length;
  $('journey-progress-fill').style.width=(100*completedCount/G.length)+'%';
  document.querySelectorAll('.hb-route-game').forEach(b=>{const isCurrent=b.dataset.route===pickedGame;
    b.classList.toggle('active',isCurrent);b.classList.toggle('completed',!!completed[b.dataset.route]);
    b.querySelector('.hb-route-status').textContent=completed[b.dataset.route]?'✓':isCurrent?'▶':'○';
    if(isCurrent)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');
  });
}
function updateStats(){
  if(!current)return;
  if(current.question?.type==='cargoRoutes'){cgTick();$('origin-mobile-score').textContent=cgCore.score(cgState);$('origin-mobile-time').textContent=$('current-time').textContent;$('round-label').textContent='4 / 6 erronka';$('header-round').textContent='4 / 6';return;}
  const maxPoints=current.total*100;
  if(current.gameId==='hasiera'||current.gameId==='industria_denbora_v1')document.querySelectorAll('.hb-milestone').forEach((el,i)=>{el.classList.toggle('current',i===current.step-1);el.classList.toggle('completed',i<current.step-1);el.setAttribute('aria-current',i===current.step-1?'step':'false');});
  const normalized=Math.min(100,Math.round(100*current.points/maxPoints));
  $('current-points').textContent=['railbuild','steamship','inventorDesk','transportConsequencesBoard','factoryProductionSimulation','enterprisePowerSimulation','industrializationEuropeMap','socialPyramidProfiles','urbanMigrationPress','workerChronology','workerMovementMatching','cityElectricGrid'].includes(current.question?.type)?(pending?.feedback?.roundPoints||0):normalized;
  $('origin-mobile-score').textContent=normalized;
  const elapsed=Math.max(0,Math.floor((Date.now()-current.localStart)/1000));
  const remaining=Math.max(0,roundTime()-elapsed);
  $('current-time').textContent=time(remaining);
  if(current.gameId==='sektoreak'&&document.getElementById('hb10-scoreval')){document.getElementById('hb10-scoreval').textContent=normalized+' / 100';document.getElementById('hb10-timeval').textContent=time(remaining);}
  $('origin-mobile-time').textContent=time(remaining);
  $('current-time').parentElement.classList.toggle('time-low',remaining<=30);
  $('round-label').textContent=`${Math.min(current.step,current.total)} / ${current.total} erronka`;
  const pct=100*Math.min(current.step-1,current.total)/current.total;
  $('progress-bar').style.width=pct+'%';
  $('header-progress-fill').style.width=pct+'%';
  $('header-round').textContent=`${Math.min(current.step,current.total)} / ${current.total}`;
  $('hb-percent').textContent=Math.round(pct)+' %';
  const xp=Math.min(100,Math.max(0,Math.round(100*current.points/Math.max(100,100*current.total))));
  $('header-xp').textContent=xp;
  $('reward-xp').textContent='+'+xp+' XP';
  $('reward-stars').textContent=normalized>=90?'★★★':normalized>=70?'★★☆':normalized>=40?'★☆☆':'☆☆☆';
  if(current.question?.type==='beforeAfterEvidence')baTick();
}
/* V10.13.39: keep 250 ms deadline checks; only paint unchanged HUD once per visible second.
   Scores and step transitions are also tracked, so no score changes are delayed. */
let hbStatsPaintSession=null,hbStatsPaintStep=-1,hbStatsPaintPoints=-1,hbStatsPaintSecond=-1,hbStatsPaintQuestion=null;
function tick(){
  if(!current||pending?.finished)return;
  if(current.question?.type==='cargoRoutes'){cgTick();return;}
  const now=Date.now(),elapsed=Math.floor(Math.max(0,now-current.localStart)/1000);
  if(current!==hbStatsPaintSession||current.step!==hbStatsPaintStep||current.points!==hbStatsPaintPoints||current.question!==hbStatsPaintQuestion||elapsed!==hbStatsPaintSecond){
    updateStats();
    hbStatsPaintSession=current;hbStatsPaintStep=current.step;hbStatsPaintPoints=current.points;
    hbStatsPaintQuestion=current.question;hbStatsPaintSecond=elapsed;
  }
  if(now-current.localStart>=roundTime()*1000&&!current.expired){current.expired=true;endEarly(true);}
}

const SPOT_LETTERS='ABCDEFGHI';
const linkColors=['#9f452e','#2c6974','#8d6728','#6d4c91','#4e794f','#a86636'];
const setInstructions=(label,instructions)=>{$('question-type').textContent=label;$('question-instructions').textContent=instructions;};
function updateReady(){
  if(!current)return;
  const q=current.question;
  if(q.type==='cityElectricGrid'){if(egPlaying)egPaint();return;}
  if(q.type==='workerMovementMatching'){if(wmPlaying)wmPaint();return;}
  if(q.type==='workerChronology'){if(chPlaying)chPaint();return;}
  if(q.type==='socialPyramidProfiles'){if(spPlaying)spPaint();return;}
  if(q.type==='urbanMigrationPress'){if(upPlaying)upPaint();return;}
  if(q.type==='industrializationEuropeMap'){if(smPlaying)smPaint();return;}
  if(q.type==='enterprisePowerSimulation'){if(epPlaying)epPaint();return;}
  if(q.type==='factoryProductionSimulation'){if(fpPlaying)fpPaint();return;}
  if(q.type==='cargoRoutes'){$('submit-answer').disabled=cgState.animating||cgTimeUp||!cgState.selectedCargo;return;}
  if(q.type==='beforeAfterEvidence'){if(baPlaying)baProgress();return;}
  if(q.type==='transportConsequencesBoard'){if(coPlaying){$('submit-answer').disabled=coState.verified||coCount()===0||!!pending;}return;}
  let ready=false;
  if(q.type==='inventorDesk')ready=dkCore.canSubmit(dkState);
  else if(q.type==='steamship')ready=ssState.selectedInnovation!==null&&(ssState.fuel>0||ssState.furnaceLit||ssState.steamLevel>0||ssState.leverEngaged);
  else if(q.type==='railbuild')ready=true;
  else if(q.type==='sectorboard')ready=q.cards.every(c=>Object.hasOwn(sectorAssignments,c.id))&&(q.extraRelations||[]).every(r=>!!sectorRelations[r.id]);
  else if(q.type==='sectorfix')ready=q.cases.every(c=>Object.hasOwn(sectorFixAnswers,c.id));
  else if(q.type==='factorysim')ready=q.scenarios.every(s=>Object.hasOwn(factoryAnswers.problems,s.id))&&factoryAnswers.conclusion!==null;
  else if(['choice','spot','year'].includes(q.type))ready=selected!==null;
  else if(q.type==='timeline'){
    ready=q.cards.every(c=>Object.hasOwn(v7Assignments,c.id));
    // The final investigation starts with six prefilled cards, three of them wrong.
    // It must not reward the untouched starting position.
    if(q.mode==='investigation')ready=ready&&q.cards.filter(c=>v7Assignments[c.id]!==q.initial?.[c.id]).length>=3;
  }
  else if(q.type==='spotmap')ready=q.labels.every(k=>Object.hasOwn(zoneAssignments,k));
  else if(q.type==='order')ready=orderItems.length===q.items.length;
  else if(q.type==='match')ready=q.left.every(t=>Object.hasOwn(matching,t));
  else if(q.type==='sort')ready=q.cards.every(t=>Object.hasOwn(sortAssignments,t.id));
  else if(q.type==='verdict')ready=q.statements.every(t=>Object.hasOwn(verdicts,t.id));
  else if(q.type==='cloze')ready=q.blanks.every(t=>Object.hasOwn(gapAnswers,t.id));
  $('submit-answer').disabled=!ready||!!pending;
  $('clear-answer').disabled=!!pending;
  $('mission-step-2').parentElement.classList.toggle('is-complete',q.type==='inventorDesk'?dkState.inspected.length===3:q.type==='steamship'?ssState.furnaceLit:q.type==='railbuild'?rbPieces.every(p=>p.slotId):ready);
  $('submit-help').textContent=ready?'Prest! Egiaztatu erantzuna.':q.type==='timeline'&&q.mode==='investigation'?`Gutxienez hiru zuzenketa egin behar dituzu (${Math.min(3,q.cards.filter(c=>v7Assignments[c.id]!==q.initial?.[c.id]).length)}/3).`:q.type==='timeline'&&q.mode==='workflow'?`Oraindik ${q.cards.length-Object.keys(v7Assignments).length} fitxa falta dira (6 guztira).`:'Osatu jarduera egiaztatu aurretik.';
}
