    const board=area.querySelector('.hb10-board'),tray=area.querySelector('.hb10-card-tray'),relations=area.querySelector('.hb10-relations');
    layout.append(board,tray);area.insertBefore(layout,bar.nextSibling);if(relations)area.append(relations);
