/* V10.5 — Illustrated machinery and shaped controls. No answer or scoring state. */
function hb105Art(atlas,cell,className){
  const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');
  const size=atlas==='textile'?[1774,887]:[1672,941],w=size[0]/2,h=size[1]/2;
  svg.setAttribute('viewBox',`${cell%2*w} ${Math.floor(cell/2)*h} ${w} ${h}`);
  svg.setAttribute('preserveAspectRatio','xMidYMid slice');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');svg.classList.add('hb105-art');
  for(const c of (className||'').split(' ').filter(Boolean))svg.classList.add(c);
  const use=document.createElementNS(ns,'use');use.setAttribute('href','#hb105-image-'+atlas);svg.append(use);return svg;
}
