 const v=[['train','Trena'],['ship','Lurrunontzia'],['wagon','Bagoia']].map(([id,label])=>`<button type="button" class="hbcg-vehicle ${cgState[id]?'is-selected':''}" data-vehicle="${id}" aria-pressed="${!!cgState[id]}"><img src="${cgAssets(id)}" alt=""><b>${label}</b></button>`).join('');
 return `<div class="hbcg-toolbar"><div class="hbcg-toolbar-group"><span class="hbcg-bar-caption">📦 Kargak · aukeratu</span>${opts}</div><div class="hbcg-toolbar-group hbcg-vehicles"><span class="hbcg-bar-caption">⚙ Garraio-txartelak</span>${v}</div></div>`;
