  $('result-score').textContent=Number(data.score||0).toLocaleString('eu-ES');
  $('result-extra').textContent=data.timedOut?'Denbora agortu da. Zure puntuak gorde dira.':`Denbora: ${data.elapsedSeconds||0} s · Gehienez 800 puntu`;
