 garraioa:'<path d="M4 17V8h12l4 5v4zM7 8V3h3v5M14 8V4h4v9M4 13h12M2 20h20"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',
 bigarrena:'<path d="M7 15c-8-9 12-14 10-3l-3 5H9zM9 20h5M10 23h3M3 4l2 2M20 4l-2 2M1 11h3M20 11h3"/>',
 hedapena:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="5" ry="10"/><path d="M2 12h20M4 6h16M4 18h16"/>',
 gizartea:'<circle cx="12" cy="5" r="3"/><circle cx="4" cy="10" r="2"/><circle cx="20" cy="10" r="2"/><path d="M7 21v-8q5-6 10 0v8M0 21v-5q4-5 7 0M17 16q4-5 7 0v5"/>',
